function Avatar({ name, small = false }: { name: string; small?: boolean }) { return <span className={`avatar ${small ? 'small' : ''}`} style={{ '--hue': String([...name].reduce((a, b) => a + b.charCodeAt(0), 0) % 360) } as React.CSSProperties}>{name.slice(0, 2).toUpperCase()}</span>; }
function Tag({ bet }: { bet: Bet }) { return <span className={`status ${bet.status}`}><i/>{({ open: 'Open challenge', matched: 'Game on', proposed: 'Result in review', disputed: 'Disputed', settled: 'Settled', refunded: 'Refunded', cancelled: 'Closed' } as Record<string, string>)[bet.status]}</span>; }
function Terms({ bet, currency }: { bet: Pick<Bet, 'rules' | 'resolver' | 'referee' | 'ends_at' | 'join_before' | 'stake' | 'side_a' | 'side_b' | 'invitee'>; currency: string }) { return <div className="terms"><div className="terms-title"><Icon name="shield" size={17}/><strong>Match rules</strong></div><p>{bet.rules}</p><dl><div><dt>Settlement</dt><dd>{resolverNames[bet.resolver]}</dd></div><div><dt>Accept before</dt><dd>{new Date(bet.join_before).toLocaleString()}</dd></div><div><dt>Result time</dt><dd>{new Date(bet.ends_at).toLocaleString()}</dd></div><div><dt>Referee</dt><dd>{bet.referee || 'None · unresolved disputes refund after 48h'}</dd></div><div><dt>Who can join</dt><dd>{bet.invitee || 'Anyone except the creator or referee'}</dd></div><div><dt>Stake per person</dt><dd>{money(bet.stake)} {currency}</dd></div></dl>{bet.resolver !== 'players' && <p className="fine-print">Automatic results are proposals from the selected source. Either player can challenge within 15 minutes. Both players may also agree on a result.</p>}<p className="fine-print">No platform cut. Unmatched stakes can be cancelled. Unresolved matched challenges refund 48 hours after result time. Terms stay fixed.</p></div>; }

function SocialShell({ immersive = false, view, navigate, openTool, children, spin, spinning, sound, toggleSound, create, count, balance, account, mode, setMode, onHome, live, error, dismissError, toast }: { immersive?:boolean; view: string; navigate: (view: string) => void; openTool: (tool: string) => void; children: ReactNode; spin: () => void; spinning: boolean; sound: boolean; toggleSound: () => void; create: () => void; count: number; balance: string; account: () => void; mode: 'practice'|'live'; setMode: (m: 'practice'|'live') => void; onHome: () => void; live: boolean; error: string; dismissError: () => void; toast: string }) {
  const menuRef = useRef<HTMLDetailsElement>(null);
  function choose(action: () => void) { if(menuRef.current) menuRef.current.open = false; action(); }
  useEffect(()=>{function outside(e:PointerEvent){if(menuRef.current&&!menuRef.current.contains(e.target as Node))menuRef.current.open=false;}function escape(e:KeyboardEvent){if(e.key==='Escape'&&menuRef.current?.open){menuRef.current.open=false;menuRef.current.querySelector('summary')?.focus();}}document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);};},[]);
  return <div className={`social-site ${immersive?'gameplay-site':''}`}><header className="site-header"><button className="site-logo" onClick={onHome} aria-label="NearFest home"><img src="/brand/nearfest-logo.svg" alt="NearFest" width="190" height="36"/></button>
    <nav className="main-nav" aria-label="Main navigation"><button className={view==='lobby'?'active':''} aria-current={view==='lobby'?'page':undefined} onClick={()=>navigate('lobby')}>Discover</button><button className={view==='mine'?'active':''} aria-current={view==='mine'?'page':undefined} onClick={()=>navigate('mine')}>My rooms</button><details className="nav-more" ref={menuRef}><summary>More <UiIcon name="chevron" size={15}/></summary><div className="nav-menu"><button onClick={()=>choose(()=>navigate('leaders'))}><Icon name="trophy" size={17}/>Leaderboard</button><button onClick={()=>choose(()=>openTool('broadcast'))}><PlatformIcon name="broadcast"/>Broadcast setup</button><button onClick={()=>choose(()=>openTool('how'))}><Icon name="chat" size={17}/>How to play</button><button onClick={()=>choose(()=>openTool('network'))}><Icon name="link" size={17}/>NEAR connection</button><span className="nav-network"><i/> NEAR testnet</span></div></details></nav>
    <div className="header-actions"><button className="header-balance" onClick={account}><Icon name="wallet" size={17}/>{balance==='INSERT PLAYER'?'Join':balance}</button><button className="header-create" onClick={create}><Icon name="plus" size={17}/>Create a challenge</button></div></header><div className="site-content" id="machine-base-screen">{children}</div><div id="machine-overlays"/>{spinning&&<div className="match-loading" role="status"><Suspense fallback={<span>✦</span>}><ArcadeScene/></Suspense><b>Finding a challenge…</b></div>}{error&&<div role="alert" className="machine-feedback error"><span>{error}</span><button aria-label="Dismiss error" onClick={dismissError}><Icon name="close" size={16}/></button></div>}{toast&&<div role="status" className="machine-feedback success"><Icon name="check" size={17}/>{toast}</div>}<footer className="site-footer"><span><i className={live?'connected':''}/>{live?'Live updates connected':'Reconnecting'} · {count} open challenges</span><button onClick={spin} disabled={spinning}>Surprise me ↗</button><SoundControls effects={sound} toggleEffects={toggleSound}/><b>Built on NEAR</b></footer></div>;
}

